window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b63487a4e717ca68"]={"versions": [{"id": "FIG-b63487a4e717ca68", "releases": ["R3.2.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm (<code>id Component Model</code>) zur Darstellung der Schichten- und Modularchitektur des AUTOSAR Memory Stacks rund um die Memory Hardware Abstraction Layer. Die Darstellung ordnet Module vertikal in Pakete bzw. Schichten (<code>NVRAM Manager</code>, <code>Memory Hardware Abstraction</code>, <code>Memory Drivers</code>) ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Paket NVRAM Manager</strong>: Übergeordnete Komponente der Serviceschicht.</li>\n<li><strong>Paket Memory Hardware Abstraction</strong>:</li>\n<li><code>Memory Hardware Abstraction::Memory Abstraction Interface</code>: Schnittstellenmodul, nach oben per Port/Socket mit dem NVRAM Manager und nach unten mit den Abstraktionsmodulen verbunden.</li>\n<li><code>Memory Hardware Abstraction::Flash EEPROM Emulation</code>: Abstraktionsmodul für Flash-Speicher.</li>\n<li><code>Memory Hardware Abstraction::EEPROM Abstraction</code>: Abstraktionsmodul für EEPROM-Speicher.</li>\n<li><strong>Paket Memory Drivers</strong>:</li>\n<li><code>Memory Drivers::Flash Driver</code>: Spezifischer Treiber für Flash-Hardware.</li>\n<li><code>Memory Drivers::EEPROM Driver</code>: Spezifischer Treiber für EEPROM-Hardware.</li>\n<li><code>Memory Drivers::Vendor Specific Library</code>: Herstellerspezifische Bibliothek, direkt angebunden an das Memory Abstraction Interface.</li>\n<li><strong>Schnittstellen</strong>:</li>\n<li>NVRAM Manager greift über Ball-and-Socket-Verbindung auf das Memory Abstraction Interface zu.</li>\n<li>Memory Abstraction Interface ist über Ball-and-Socket-Verbindungen an Flash EEPROM Emulation und EEPROM Abstraction angebunden.</li>\n<li>Memory Abstraction Interface besitzt eine direkte Ball-and-Socket-Verbindung zur Vendor Specific Library.</li>\n<li>Flash EEPROM Emulation ist über Ball-and-Socket mit dem Flash Driver verbunden.</li>\n<li>EEPROM Abstraction ist über Ball-and-Socket mit dem EEPROM Driver verbunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Struktur- und Schichtenübersicht ohne explizite Ablauf- oder Zeitsequenzen. Aufrufe und Datenflüsse erfolgen top-down vom NVRAM Manager über das Memory Abstraction Interface, welches Zugriffe entweder über die Flash EEPROM Emulation an den Flash Driver, über die EEPROM Abstraction an den EEPROM Driver oder direkt an herstellerspezifische Bibliotheken (<code>Vendor Specific Library</code>) leitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Einordnung des Moduls EEPROM Abstraction: Das Modul kapselt EEPROM-Hardwaretreiber (<code>EEPROM Driver</code>) und stellt ein einheitliches Adressierungs- und Zugriffsschema über das <code>Memory Abstraction Interface</code> für den NVRAM Manager bereit. Der Zugriff auf Nichtflüchtigen Speicher kann parallel über EEPROM Abstraction oder Flash EEPROM Emulation erfolgen.</p>"}, {"id": "FIG-8422ff1ad6671f9e", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm (<code>id Component Model</code>) zur Darstellung der Schichten- und Modularchitektur des AUTOSAR Memory Stacks rund um die Memory Hardware Abstraction Layer. Die Darstellung ordnet Module vertikal in Pakete bzw. Schichten (<code>NVRAM Manager</code>, <code>Memory Hardware Abstraction</code>, <code>Memory Drivers</code>) ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Paket NVRAM Manager</strong>: Übergeordnete Komponente der Serviceschicht.</li>\n<li><strong>Paket Memory Hardware Abstraction</strong>:</li>\n<li><code>Memory Hardware Abstraction::Memory Abstraction Interface</code>: Schnittstellenmodul, nach oben per Port/Socket mit dem NVRAM Manager und nach unten mit den Abstraktionsmodulen verbunden.</li>\n<li><code>Memory Hardware Abstraction::Flash EEPROM Emulation</code>: Abstraktionsmodul für Flash-Speicher.</li>\n<li><code>Memory Hardware Abstraction::EEPROM Abstraction</code>: Abstraktionsmodul für EEPROM-Speicher.</li>\n<li><strong>Paket Memory Drivers</strong>:</li>\n<li><code>Memory Drivers::Flash Driver</code>: Spezifischer Treiber für Flash-Hardware.</li>\n<li><code>Memory Drivers::EEPROM Driver</code>: Spezifischer Treiber für EEPROM-Hardware.</li>\n<li><code>Memory Drivers::Vendor Specific Library</code>: Herstellerspezifische Bibliothek, direkt angebunden an das Memory Abstraction Interface.</li>\n<li><strong>Schnittstellen</strong>:</li>\n<li>NVRAM Manager greift über Ball-and-Socket-Verbindung auf das Memory Abstraction Interface zu.</li>\n<li>Memory Abstraction Interface ist über Ball-and-Socket-Verbindungen an Flash EEPROM Emulation und EEPROM Abstraction angebunden.</li>\n<li>Memory Abstraction Interface besitzt eine direkte Ball-and-Socket-Verbindung zur Vendor Specific Library.</li>\n<li>Flash EEPROM Emulation ist über Ball-and-Socket mit dem Flash Driver verbunden.</li>\n<li>EEPROM Abstraction ist über Ball-and-Socket mit dem EEPROM Driver verbunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Struktur- und Schichtenübersicht ohne explizite Ablauf- oder Zeitsequenzen. Aufrufe und Datenflüsse erfolgen top-down vom NVRAM Manager über das Memory Abstraction Interface, welches Zugriffe entweder über die Flash EEPROM Emulation an den Flash Driver, über die EEPROM Abstraction an den EEPROM Driver oder direkt an herstellerspezifische Bibliotheken (<code>Vendor Specific Library</code>) leitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Einordnung des Moduls EEPROM Abstraction: Das Modul kapselt EEPROM-Hardwaretreiber (<code>EEPROM Driver</code>) und stellt ein einheitliches Adressierungs- und Zugriffsschema über das <code>Memory Abstraction Interface</code> für den NVRAM Manager bereit. Der Zugriff auf Nichtflüchtigen Speicher kann parallel über EEPROM Abstraction oder Flash EEPROM Emulation erfolgen.</p>"}, {"id": "FIG-c8064655ef6a9e28", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm (<code>id Component Model</code>) zur Darstellung der Schichten- und Modularchitektur des AUTOSAR Memory Stacks rund um die Memory Hardware Abstraction Layer. Die Darstellung ordnet Module vertikal in Pakete bzw. Schichten (<code>NVRAM Manager</code>, <code>Memory Hardware Abstraction</code>, <code>Memory Drivers</code>) ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Paket NVRAM Manager</strong>: Übergeordnete Komponente der Serviceschicht.</li>\n<li><strong>Paket Memory Hardware Abstraction</strong>:</li>\n<li><code>Memory Hardware Abstraction::Memory Abstraction Interface</code>: Schnittstellenmodul, nach oben per Port/Socket mit dem NVRAM Manager und nach unten mit den Abstraktionsmodulen verbunden.</li>\n<li><code>Memory Hardware Abstraction::Flash EEPROM Emulation</code>: Abstraktionsmodul für Flash-Speicher.</li>\n<li><code>Memory Hardware Abstraction::EEPROM Abstraction</code>: Abstraktionsmodul für EEPROM-Speicher.</li>\n<li><strong>Paket Memory Drivers</strong>:</li>\n<li><code>Memory Drivers::Flash Driver</code>: Spezifischer Treiber für Flash-Hardware.</li>\n<li><code>Memory Drivers::EEPROM Driver</code>: Spezifischer Treiber für EEPROM-Hardware.</li>\n<li><code>Memory Drivers::Vendor Specific Library</code>: Herstellerspezifische Bibliothek, direkt angebunden an das Memory Abstraction Interface.</li>\n<li><strong>Schnittstellen</strong>:</li>\n<li>NVRAM Manager greift über Ball-and-Socket-Verbindung auf das Memory Abstraction Interface zu.</li>\n<li>Memory Abstraction Interface ist über Ball-and-Socket-Verbindungen an Flash EEPROM Emulation und EEPROM Abstraction angebunden.</li>\n<li>Memory Abstraction Interface besitzt eine direkte Ball-and-Socket-Verbindung zur Vendor Specific Library.</li>\n<li>Flash EEPROM Emulation ist über Ball-and-Socket mit dem Flash Driver verbunden.</li>\n<li>EEPROM Abstraction ist über Ball-and-Socket mit dem EEPROM Driver verbunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Struktur- und Schichtenübersicht ohne explizite Ablauf- oder Zeitsequenzen. Aufrufe und Datenflüsse erfolgen top-down vom NVRAM Manager über das Memory Abstraction Interface, welches Zugriffe entweder über die Flash EEPROM Emulation an den Flash Driver, über die EEPROM Abstraction an den EEPROM Driver oder direkt an herstellerspezifische Bibliotheken (<code>Vendor Specific Library</code>) leitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Einordnung des Moduls EEPROM Abstraction: Das Modul kapselt EEPROM-Hardwaretreiber (<code>EEPROM Driver</code>) und stellt ein einheitliches Adressierungs- und Zugriffsschema über das <code>Memory Abstraction Interface</code> für den NVRAM Manager bereit. Der Zugriff auf Nichtflüchtigen Speicher kann parallel über EEPROM Abstraction oder Flash EEPROM Emulation erfolgen.</p>"}, {"id": "FIG-9556dd5d7bae11a7", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Modulübersichtsdiagramm der Speicherabstraktion und Treiberarchitektur im AUTOSAR-Basissoftware-Stack. Die Darstellung strukturiert die Speicherverwaltung vertikal in vier Hauptschichten bzw. Pakete (<code>NVRAM Manager</code>, <code>Memory Hardware Abstraction</code>, <code>Memory Access</code>, <code>Memory Drivers</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Paket NVRAM Manager</strong>: Oberste Speichermanagement-Schicht.</li>\n<li><strong>Paket Memory Hardware Abstraction</strong>:</li>\n<li><code>Memory Hardware Abstraction::Memory Abstraction Interface</code></li>\n<li><code>Memory Hardware Abstraction::Flash EEPROM Emulation</code></li>\n<li><code>Memory Hardware Abstraction::EEPROM Abstraction</code></li>\n<li><strong>Paket Memory Access</strong>: Zwischenschicht zwischen Hardware-Abstraktion und Treiberschicht.</li>\n<li><strong>Paket Memory Drivers</strong>:</li>\n<li><code>Memory Drivers::Memory Driver</code>: Generischer Speichertreiberblock.</li>\n<li><code>Memory Drivers::Vendor Specific Library</code>: Herstellerspezifische Bibliothek.</li>\n<li><strong>Schnittstellen/Verbindungen</strong>: Keine expliziten Konnektoren oder Schnittstellenbezeichner zwischen den Paketen oder Modulen eingezeichnet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schichtenmodell ohne Sequenz- oder Kontrollflussdarstellung. Die Schichtung indiziert eine hierarchische Entkopplung von der Serviceschicht (<code>NVRAM Manager</code>) über Abstraktions- und Zwischenschichten (<code>Memory Hardware Abstraction</code>, <code>Memory Access</code>) hin zu Treibern und herstellerspezifischen Bibliotheken (<code>Memory Drivers</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe zur Strukturierung des Speicherstacks. Die hardwarenahe Treiberebene ist unter <code>Memory Driver</code> zusammengefasst und durch das Paket <code>Memory Access</code> von der <code>Memory Hardware Abstraction</code> (<code>EEPROM Abstraction</code>, <code>Flash EEPROM Emulation</code>, <code>Memory Abstraction Interface</code>) entkoppelt.</p>"}, {"id": "FIG-f9508e80b89225ea", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Modulübersichtsdiagramm der Speicherabstraktion und Treiberarchitektur im AUTOSAR-Basissoftware-Stack. Die Darstellung strukturiert die Speicherverwaltung vertikal in vier Hauptschichten bzw. Pakete (<code>NVRAM Manager</code>, <code>Memory Hardware Abstraction</code>, <code>Memory Access</code>, <code>Memory Drivers</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Paket NVRAM Manager</strong>: Oberste Speichermanagement-Schicht.</li>\n<li><strong>Paket Memory Hardware Abstraction</strong>:</li>\n<li><code>Memory Hardware Abstraction::Memory Abstraction Interface</code></li>\n<li><code>Memory Hardware Abstraction::Flash EEPROM Emulation</code></li>\n<li><code>Memory Hardware Abstraction::EEPROM Abstraction</code></li>\n<li><strong>Paket Memory Access</strong>: Zwischenschicht zwischen Hardware-Abstraktion und Treiberschicht.</li>\n<li><strong>Paket Memory Drivers</strong>:</li>\n<li><code>Memory Drivers::Memory Driver</code>: Generischer Speichertreiberblock.</li>\n<li><code>Memory Drivers::Vendor Specific Library</code>: Herstellerspezifische Bibliothek.</li>\n<li><strong>Schnittstellen/Verbindungen</strong>: Keine expliziten Konnektoren oder Schnittstellenbezeichner zwischen den Paketen oder Modulen eingezeichnet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schichtenmodell ohne Sequenz- oder Kontrollflussdarstellung. Die Schichtung indiziert eine hierarchische Entkopplung von der Serviceschicht (<code>NVRAM Manager</code>) über Abstraktions- und Zwischenschichten (<code>Memory Hardware Abstraction</code>, <code>Memory Access</code>) hin zu Treibern und herstellerspezifischen Bibliotheken (<code>Memory Drivers</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe zur Strukturierung des Speicherstacks. Die hardwarenahe Treiberebene ist unter <code>Memory Driver</code> zusammengefasst und durch das Paket <code>Memory Access</code> von der <code>Memory Hardware Abstraction</code> (<code>EEPROM Abstraction</code>, <code>Flash EEPROM Emulation</code>, <code>Memory Abstraction Interface</code>) entkoppelt.</p>"}], "trans": [{"from": "FIG-b63487a4e717ca68", "to": "FIG-8422ff1ad6671f9e", "fr": "R4.1.3", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8422ff1ad6671f9e", "to": "FIG-c8064655ef6a9e28", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c8064655ef6a9e28", "to": "FIG-9556dd5d7bae11a7", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Rahmenkopf <code>id Component Model</code> sowie UML-Komponenten-Symbole an den inneren Blöcken entfernt.</li>\n<li>Zwischen den Paketen <code>Memory Hardware Abstraction</code> und <code>Memory Drivers</code> wurde ein neues Paket <code>Memory Access</code> eingefügt.</li>\n<li>Die Komponenten <code>Memory Drivers::Flash Driver</code> und <code>Memory Drivers::EEPROM Driver</code> wurden zu einer einzigen Komponente <code>Memory Drivers::Memory Driver</code> zusammengefasst.</li>\n<li>Sämtliche Schnittstellenverbindungen (Lollipop-/Socket-Konnektoren) zwischen den Schichten und Komponenten wurden entfernt.</li>\n</ul>"}, {"from": "FIG-9556dd5d7bae11a7", "to": "FIG-f9508e80b89225ea", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Über dem äußeren Diagrammrahmen abgeschnittener Textrest am oberen Bildrand entfernt.</li>\n</ul>"}]};
